using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF9 breaking change: Migrate() can no longer be called within a manual
    // transaction. EF9 always wraps each migration in its own transaction.
    // Fix: remove the outer transaction wrapping.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

