using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Cosmos;

// ─── Cosmos DB EF Core 9 Breaking Changes & Fixes ───

// ENTITY MODELS
class Product
{
    public string Id { get; set; } = default!;
    public string Category { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // ══════════════════════════════════════════════════════════════
            // BREAKING CHANGE 1: Discriminator property renamed
            // ══════════════════════════════════════════════════════════════
            // In EF Core 9, the Cosmos provider changed the default
            // discriminator property from "Discriminator" to "$type".
            //
            // If you have EXISTING documents using "Discriminator", you
            // must explicitly configure it to keep the old property name:
            b.HasDiscriminator<string>("Discriminator")
                .HasValue<Product>("Product")
                .HasValue<DiscountedProduct>("DiscountedProduct");
        });
    }

    // ══════════════════════════════════════════════════════════════════════
    // BREAKING CHANGE 2: Synchronous I/O no longer supported
    // ══════════════════════════════════════════════════════════════════════
    // EF Core 9 Cosmos provider removed synchronous query/save support.
    // Calls like .ToList(), .First(), .SaveChanges() throw
    // InvalidOperationException.
    //
    // FIX: Replace all sync calls with async equivalents.

    // ❌ BEFORE (EF8 — sync, now throws in EF9):
    // public List<Product> GetProducts()
    // {
    //     return Products.Where(p => p.Category == "Electronics").ToList();
    // }

    // ✅ AFTER (EF9 — async):
    public async Task<List<Product>> GetProductsAsync()
    {
        return await Products
            .Where(p => p.Category == "Electronics")
            .ToListAsync();
    }

    // ❌ BEFORE (sync save):
    // public void AddProduct(Product p)
    // {
    //     Products.Add(p);
    //     SaveChanges();
    // }

    // ✅ AFTER (async save):
    public async Task AddProductAsync(Product p)
    {
        Products.Add(p);
        await SaveChangesAsync();
    }
}

